const g=W.groundAt(c[0]+dx*D,c[1]+dz*D), eye=[c[0]-dx*E,g+1.3,c[1]-dz*E], at=[c[0]+dx*D,g+1.0,c[1]+dz*D];
const ap=bend.rig.apply.bind(bend.rig); bend.rig.apply=(cam,w,h)=>{ap(cam,w,h); cam.lookAt(eye,at); cam.update(w,h);};
